'use client';

import React, { useState } from 'react';
import { X, Upload, ScanLine } from 'lucide-react';
import { Button, Input } from './base';
import { useTransactions } from '@/lib/transaction-context';

interface AddTransactionModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function AddTransactionModal({ isOpen, onClose }: AddTransactionModalProps) {
  const { addTransaction } = useTransactions();
  const [type, setType] = useState<'Income' | 'Expense'>('Income');
  const [isScanning, setIsScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  
  // Form State
  const [title, setTitle] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [paymentMethod, setPaymentMethod] = useState('Card');

  if (!isOpen) return null;

  const handleScan = () => {
    setIsScanning(true);
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      setScanProgress(progress);
      if (progress >= 100) {
        clearInterval(interval);
        setIsScanning(false);
        // Mock filling data
        setTitle('Scanned Receipt - Walmart');
        setAmount('45.50');
        setCategory('Food');
        setType('Expense');
      }
    }, 200);
  };

  const handleSubmit = () => {
    if (!title || !amount || !category) return;

    addTransaction({
      description: title,
      amount: parseFloat(amount),
      category,
      date,
      type,
      paymentMethod,
      status: 'Completed'
    });

    // Reset form
    setTitle('');
    setAmount('');
    setCategory('');
    setType('Income');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-md max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center p-6 border-b">
          <div>
            <h2 className="text-xl font-bold">Add Transaction</h2>
            <p className="text-sm text-gray-500">Add a new transaction to track your finances</p>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            <X size={24} />
          </button>
        </div>

        <div className="p-6 space-y-6">
          {/* AI Scan Receipt */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">AI Scan Receipt</label>
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 flex items-center gap-4">
              <div className="bg-gray-100 p-3 rounded-lg">
                <ScanLine size={24} className="text-gray-500" />
              </div>
              <div className="flex-1">
                {!isScanning ? (
                  <div className="flex items-center gap-2">
                    <Button variant="primary" size="sm" onClick={handleScan} className="bg-green-500 hover:bg-green-600">
                      Choose File
                    </Button>
                    <span className="text-sm text-gray-500">No file chosen</span>
                  </div>
                ) : (
                  <div className="w-full">
                    <div className="flex justify-between text-xs mb-1">
                      <span>Scanning receipt...</span>
                      <span>{scanProgress}%</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div 
                        className="bg-green-500 h-2 rounded-full transition-all duration-200" 
                        style={{ width: `${scanProgress}%` }}
                      />
                    </div>
                  </div>
                )}
                <p className="text-xs text-gray-400 mt-1">JPG, PNG up to 2MB</p>
              </div>
            </div>
          </div>

          {/* Transaction Type */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Transaction Type</label>
            <div className="flex gap-4">
              <button
                className={`flex-1 py-2 px-4 rounded-md border ${type === 'Income' ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-200 text-gray-600'}`}
                onClick={() => setType('Income')}
              >
                Income
              </button>
              <button
                className={`flex-1 py-2 px-4 rounded-md border ${type === 'Expense' ? 'border-red-500 bg-red-50 text-red-700' : 'border-gray-200 text-gray-600'}`}
                onClick={() => setType('Expense')}
              >
                Expense
              </button>
            </div>
          </div>

          {/* Form Fields */}
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Title</label>
              <Input 
                placeholder="Transaction title" 
                value={title}
                onChange={(e) => setTitle(e.target.value)}
              />
            </div>
            
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Amount</label>
              <Input 
                placeholder="0.00" 
                type="number" 
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
              <select 
                className="w-full rounded-md border border-gray-300 p-2 text-sm focus:ring-2 focus:ring-green-500 focus:border-transparent"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                <option value="">Select a category</option>
                <option value="Freelance">Freelance</option>
                <option value="Salary">Salary</option>
                <option value="Food">Food</option>
                <option value="Transport">Transport</option>
                <option value="Housing">Housing</option>
                <option value="Utilities">Utilities</option>
                <option value="Entertainment">Entertainment</option>
                <option value="Supplies">Supplies</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
              <Input 
                type="date" 
                value={date}
                onChange={(e) => setDate(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Payment Method</label>
              <select 
                className="w-full rounded-md border border-gray-300 p-2 text-sm focus:ring-2 focus:ring-green-500 focus:border-transparent"
                value={paymentMethod}
                onChange={(e) => setPaymentMethod(e.target.value)}
              >
                <option value="Card">Card</option>
                <option value="Bank Transfer">Bank Transfer</option>
                <option value="Cash">Cash</option>
                <option value="PayPal">PayPal</option>
              </select>
            </div>

            <div className="flex items-center justify-between py-2">
              <div>
                <p className="font-medium text-sm">Recurring Transaction</p>
                <p className="text-xs text-gray-500">Set recurring to repeat this transaction</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" className="sr-only peer" />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-green-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-600"></div>
              </label>
            </div>

            <div className="pt-4 flex gap-3">
              <Button variant="outline" className="flex-1" onClick={onClose}>Cancel</Button>
              <Button variant="primary" className="flex-1 bg-green-500 hover:bg-green-600" onClick={handleSubmit}>
                Add Transaction
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
